def splitVector {I : Type} (J : I → Set ℕ) (b : I → Set Point)
    (hs : ∀ i, Splits (J i) (b i)) (i : I) : antisymmetricJL (splitFamily J b) :=
  ⟨characteristic (b i) - characteristic (cylinder (J i) \ b i),split_difference_mem J b hs i⟩

